import base64
import tkinter as tk
from io import BytesIO
from PIL import Image

FAVICON_B64_48 = """

"""

FAVICON_B64_28 = """

"""


def load_favicon(root):
    """Load icons from embedded base64 PNGs. Returns (window_icon, header_icon)."""
    try:
        png_48 = base64.b64decode(FAVICON_B64_48)

        # Window icon — native tk.PhotoImage preserves PNG alpha in Tk 8.6+
        favicon_window = tk.PhotoImage(data=png_48)
        root.iconphoto(True, favicon_window)

        # Header icon — resize via PIL, re-encode as PNG, load with tk.PhotoImage
        img = Image.open(BytesIO(png_48)).resize((36, 36), Image.LANCZOS)
        buf = BytesIO()
        img.save(buf, format="PNG")
        favicon_header = tk.PhotoImage(data=buf.getvalue())

        return favicon_window, favicon_header
    except Exception:
        return None, None

